1. @* Pagination controls: Previous, numbered pages, Next *@
2. 
3. @if (TotalPages > 1)
4. {
5.     <nav aria-label="Product pagination" class="mt-4">
6.         <ul class="pagination justify-content-center mb-0">
7.             <li class="page-item @(CurrentPage == 1 ? "disabled" : "")">
8.                 <button class="page-link" @onclick="@(() => GoToPage(CurrentPage - 1))" disabled="@(CurrentPage == 1)">
9.                     Previous
10.                 </button>
11.             </li>
12. 
13.             @foreach (var page in PageNumbers)
14.             {
15.                 <li class="page-item @(page == CurrentPage ? "active" : "")" @key="@page">
16.                     <button class="page-link" @onclick="@(() => GoToPage(page))">@page</button>
17.                 </li>
18.             }
19. 
20.             <li class="page-item @(CurrentPage == TotalPages ? "disabled" : "")">
21.                 <button class="page-link" @onclick="@(() => GoToPage(CurrentPage + 1))" disabled="@(CurrentPage == TotalPages)">
22.                     Next
23.                 </button>
24.             </li>
25.         </ul>
26.     </nav>
27. }
28. 
29. @code {
30.     [Parameter]
31.     public int CurrentPage { get; set; } = 1;
32. 
33.     [Parameter]
34.     public int TotalPages { get; set; }
35. 
36.     [Parameter]
37.     public EventCallback<int> OnPageChanged { get; set; }
38. 
39.     private IEnumerable<int> PageNumbers
40.     {
41.         get
42.         {
43.             // Show up to 5 page numbers centered around current page
44.             int start = Math.Max(1, CurrentPage - 2);
45.             int end = Math.Min(TotalPages, start + 4);
46.             start = Math.Max(1, end - 4);
47.             return Enumerable.Range(start, end - start + 1);
48.         }
49.     }
50. 
51.     private async Task GoToPage(int page)
52.     {
53.         if (page >= 1 && page <= TotalPages && page != CurrentPage)
54.         {
55.             await OnPageChanged.InvokeAsync(page);
56.         }
57.     }
58. }
59.

